    abs_vals = sorted(list(abs_vals))
    num_abs = len(abs_vals)

    # If num_abs is too large, solve_small will be too slow.
    # But for small n, it should be okay.

    max_score = 0
    # We only need to try 2^num_abs combinations.
    # To speed up, we can use a random search if num_abs is large.
    if num_abs <= 20:
        for choices in itertools.product([1, -1], repeat=num_abs):
            erased = set()
            for j in range(num_abs):
                if choices[j] == 1:
                    erased.add(abs_vals[j])
                else:
                    erased.add(-abs_vals[j])
            score = 0
            for a, b in pairs:
                if a in erased or b in erased:
                    score += 1
            if score > max_score:
                max_score = score
    else:
        # Random search
        for _ in range(10000):
            erased = set()
            for v in abs_vals:
                if random.random() > 0.5:
                    erased.add(v)
                else:
                    erased.add(-v)
            score = 0
            for a, b in pairs:
                if a in erased or b in erased:
                    score += 1
            if score > max_score:
                max_score = score
    return max_score

